/**
 * Amazon Integration Module
 *
 * Host wiring for the Amazon plugin. The foundation needs no NestJS providers
 * of its own (no repository, no lock: the LWA token is minted statelessly and
 * cached through the host `CachePort`), so the module is generated by
 * `createNestAdapterModule`, like DPD.
 *
 * Wired into `apps/api/src/plugins.ts` and `apps/worker/src/plugins.ts`.
 *
 * @module libs/integrations/amazon/src
 */
import type { DynamicModule } from '@nestjs/common';
import { createNestAdapterModule } from '@openlinker/plugin-sdk';

import { createAmazonPlugin } from './amazon-plugin';

export const AmazonIntegrationModule: DynamicModule = createNestAdapterModule({
  plugin: createAmazonPlugin(),
});
